proc typeMetadata*(key: uint32): ptr TypeMetadata =
  var low = 0
  var high = TypeRegistry.high
  while low <= high:
    let middle = (low + high) shr 1
    if TypeRegistry[middle].key == key: return unsafeAddr TypeRegistry[middle]
    if TypeRegistry[middle].key < key: low = middle + 1
    else: high = middle - 1

proc propertyMetadata*(key: uint32): ptr PropertyMetadata =
  var low = 0
  var high = PropertyRegistry.high
  while low <= high:
    let middle = (low + high) shr 1
    if PropertyRegistry[middle].key == key: return unsafeAddr PropertyRegistry[middle]
    if PropertyRegistry[middle].key < key: low = middle + 1
    else: high = middle - 1

proc registerFactory*(factories: var seq[tuple[key: uint32, factory: CoreFactoryProc]];
    key: uint32; factory: CoreFactoryProc) =
  if typeMetadata(key).isNil: raise newException(ValueError, "unknown generated type key")
  for item in factories:
    if item.key == key: raise newException(ValueError, "duplicate core factory")
  factories.add (key, factory)

proc instantiate*(factories: openArray[tuple[key: uint32, factory: CoreFactoryProc]];
    key: uint32): GeneratedCoreObject =
  for item in factories:
    if item.key == key:
      result = item.factory()
      result.typeKey = key
      return
